"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["69770"],{14397(e){e.exports=JSON.parse('{"id":"FIN-309","slug":"public-good","term":"Public Good","also_known_as":[],"difficulty":"Intermediate","definition":"A public good is a product or service that is non-excludable, meaning people cannot easily be prevented from using it, and non-rivalrous, meaning one person\'s use does not reduce its availability to others.","explanation":["Classic examples of public goods include national defence, street lighting, flood defences and public fireworks displays. Once street lights are installed, everyone walking down the street benefits, and one person\'s use does not leave less light for anyone else.","Public goods create a problem for private markets, called the free-rider problem. Because people can benefit without paying, many will choose not to pay. A private company would struggle to sell street lighting to individual residents, because each might wait for others to pay and then enjoy the light for free.","As a result, public goods tend to be underprovided if left to the market. This is why governments usually provide them and fund them through taxation.","Few goods are perfectly public. Some, like a free public park, can become crowded, which makes them partly rivalrous. Others, like a toll road, can exclude non-payers. Economists therefore treat public goods as one end of a range, with private goods at the other end."],"note":"","total":1500,"prev":{"slug":"public-company","term":"Public Company"},"next":{"slug":"pump-and-dump","term":"Pump and Dump"}}')}}]);